  Fatal fatal=new Fatal();RuntimeException ordinary=new IllegalStateException("qualified direct ordinary");boolean[] fired={false};List<Object> selected=new ArrayList<>();Trace trace=new Trace();OutcomeCapture outcomes=new OutcomeCapture();Throwable escaped=null,validation=null,cleanupFailure=null;boolean result=false;
  boolean precall=Set.of("terminal","dirty","stale","changing").contains(state);
