    if(state.startsWith("terminal-"))owner.close();else if(state.startsWith("dirty-"))owner.onPause();else if(state.equals("ordinary-throw-after-callback"))throw ordinary;else if(state.equals("fatal")||state.equals("fatal-throw-after-callback"))throw fatal;
    else if(state.equals("successor")&&!natural(family)){NativeBridge.preparedPacket=packet(2,"helloz");edit.hostReplace(edit.getText().length(),edit.getText().length(),"z");}
