   try{result=operation(c,family);}catch(RuntimeException|Error f){escaped=f;}ConcreteHostProbe.clearQualificationHook(selectedHook);row.put("operation_end_sequence",trace.sequence.size());row.put("post_operation_authority",TraceRunner.authority(target));row.put("actual_operation_outcome",escaped==null?OutcomeCapture.actual(result):Map.of("kind","exception","class",escaped.getClass().getName(),"identity",identity(escaped)));row.put("observed_result",result);row.put("escaped_class",escaped==null?null:escaped.getClass().getName());row.put("escaped_exact_injected_identity",escaped==fatal?"fatal":escaped==ordinary?"ordinary":escaped==null?null:"other");row.put("native_target_entries",ConcreteHostProbe.count(leaf(family),"entry"));row.put("selected_hook_fired",fired[0]);row.put("jni_prepare_delta",NativeBridge.prepareCalls-prepared);row.put("jni_commit_delta",NativeBridge.commitCalls-commits);row.put("post_text",edit.getText().toString());row.put("same_editable",edit.getText()==buffer);row.put("presentation_changed",original.fence.presentation!=originalToken);row.put("original_result_expected",(state.equals("current")||state.equals("successor"))&&!family.equals("performContextMenuAction"));
